58	func NewCmdCreate(f *cmdutil.Factory, runF func(*CreateOptions) error) *cobra.Command {
59		opts := &CreateOptions{
60			IO:         f.IOStreams,
61			HttpClient: f.HttpClient,
62			GitClient:  f.GitClient,
63			Config:     f.Config,
64			Prompter:   f.Prompter,
65		}
66	
67		var enableIssues bool
68		var enableWiki bool
69	
70		cmd := &cobra.Command{
71			Use:   "create [<name>]",
72			Short: "Create a new repository",
73			Long: heredoc.Docf(`
74				Create a new GitHub repository.
75	
76				To create a repository interactively, use %[1]sgh repo create%[1]s with no arguments.
77	
78				To create a remote repository non-interactively, supply the repository name and one of %[1]s--public%[1]s, %[1]s--private%[1]s, or %[1]s--internal%[1]s.
79				Pass %[1]s--clone%[1]s to clone the new repository locally.
80	
81				To create a remote repository from an existing local repository, specify the source directory with %[1]s--source%[1]s.
82				By default, the remote repository name will be the name of the source directory.
83				Pass %[1]s--push%[1]s to push any local commits to the new repository.
84			`, "`"),
85			Example: heredoc.Doc(`
86				# create a repository interactively
87				gh repo create
88	
89				# create a new remote repository and clone it locally
90				gh repo create my-project --public --clone
91	
92				# create a remote repository from the current directory
93				gh repo create my-project --private --source=. --remote=upstream
94			`),
95			Args:    cobra.MaximumNArgs(1),
96			Aliases: []string{"new"},
97			RunE: func(cmd *cobra.Command, args []string) error {
98				if len(args) > 0 {
99					opts.Name = args[0]
100				}
101	
102				if len(args) == 0 && cmd.Flags().NFlag() == 0 {
103					if !opts.IO.CanPrompt() {
104						return cmdutil.FlagErrorf("at least one argument required in non-interactive mode")
105					}
106					opts.Interactive = true
107				} else {
108					// exactly one visibility flag required
109					if !opts.Public && !opts.Private && !opts.Internal {
110						return cmdutil.FlagErrorf("`--public`, `--private`, or `--internal` required when not running interactively")
111					}
112					err := cmdutil.MutuallyExclusive(
113						"expected exactly one of `--public`, `--private`, or `--internal`",
114						opts.Public, opts.Private, opts.Internal)
115					if err != nil {
116						return err
117					}
118	
119					if opts.Public {
120						opts.Visibility = "PUBLIC"
121					} else if opts.Private {
122						opts.Visibility = "PRIVATE"
123					} else {
124						opts.Visibility = "INTERNAL"
125					}
126				}
127	
128				if opts.Source == "" {
129					if opts.Remote != "" {
130						return cmdutil.FlagErrorf("the `--remote` option can only be used with `--source`")
131					}
132					if opts.Push {
133						return cmdutil.FlagErrorf("the `--push` option can only be used with `--source`")
134					}
135					if opts.Name == "" && !opts.Interactive {
136						return cmdutil.FlagErrorf("name argument required to create new remote repository")
137					}
138	
139				} else if opts.Clone || opts.GitIgnoreTemplate != "" || opts.LicenseTemplate != "" || opts.Template != "" {
140					return cmdutil.FlagErrorf("the `--source` option is not supported with `--clone`, `--template`, `--license`, or `--gitignore`")
141				}
142	
143				if opts.Template != "" && (opts.GitIgnoreTemplate != "" || opts.LicenseTemplate != "") {
144					return cmdutil.FlagErrorf(".gitignore and license templates are not added when template is provided")
145				}
146	
147				if opts.Template != "" && opts.AddReadme {
148					return cmdutil.FlagErrorf("the `--add-readme` option is not supported with `--template`")
149				}
150	
151				if cmd.Flags().Changed("enable-issues") {
152					opts.DisableIssues = !enableIssues
153				}
154				if cmd.Flags().Changed("enable-wiki") {
155					opts.DisableWiki = !enableWiki
156				}
157				if opts.Template != "" && (opts.Homepage != "" || opts.Team != "" || opts.DisableIssues || opts.DisableWiki) {
158					return cmdutil.FlagErrorf("the `--template` option is not supported with `--homepage`, `--team`, `--disable-issues`, or `--disable-wiki`")
159				}
160	
161				if opts.Template == "" && opts.IncludeAllBranches {
162					return cmdutil.FlagErrorf("the `--include-all-branches` option is only supported when using `--template`")
163				}
164	
165				if runF != nil {
166					return runF(opts)
167				}
168				return createRun(opts)
169			},
170		}
171	
172		cmd.Flags().StringVarP(&opts.Description, "description", "d", "", "Description of the repository")
173		cmd.Flags().StringVarP(&opts.Homepage, "homepage", "h", "", "Repository home page `URL`")
174		cmd.Flags().StringVarP(&opts.Team, "team", "t", "", "The `name` of the organization team to be granted access")
175		cmd.Flags().StringVarP(&opts.Template, "template", "p", "", "Make the new repository based on a template `repository`")
176		cmd.Flags().BoolVar(&opts.Public, "public", false, "Make the new repository public")
177		cmd.Flags().BoolVar(&opts.Private, "private", false, "Make the new repository private")
178		cmd.Flags().BoolVar(&opts.Internal, "internal", false, "Make the new repository internal")
179		cmd.Flags().StringVarP(&opts.GitIgnoreTemplate, "gitignore", "g", "", "Specify a gitignore template for the repository")
180		cmd.Flags().StringVarP(&opts.LicenseTemplate, "license", "l", "", "Specify an Open Source License for the repository")
181		cmd.Flags().StringVarP(&opts.Source, "source", "s", "", "Specify path to local repository to use as source")
182		cmd.Flags().StringVarP(&opts.Remote, "remote", "r", "", "Specify remote name for the new repository")
183		cmd.Flags().BoolVar(&opts.Push, "push", false, "Push local commits to the new repository")
184		cmd.Flags().BoolVarP(&opts.Clone, "clone", "c", false, "Clone the new repository to the current directory")
185		cmd.Flags().BoolVar(&opts.DisableIssues, "disable-issues", false, "Disable issues in the new repository")
186		cmd.Flags().BoolVar(&opts.DisableWiki, "disable-wiki", false, "Disable wiki in the new repository")
187		cmd.Flags().BoolVar(&opts.IncludeAllBranches, "include-all-branches", false, "Include all branches from template repository")
188		cmd.Flags().BoolVar(&opts.AddReadme, "add-readme", false, "Add a README file to the new repository")
189	
190		// deprecated flags
191		cmd.Flags().BoolP("confirm", "y", false, "Skip the confirmation prompt")
192		cmd.Flags().BoolVar(&enableIssues, "enable-issues", true, "Enable issues in the new repository")
193		cmd.Flags().BoolVar(&enableWiki, "enable-wiki", true, "Enable wiki in the new repository")
194	
195		_ = cmd.Flags().MarkDeprecated("confirm", "Pass any argument to skip confirmation prompt")
196		_ = cmd.Flags().MarkDeprecated("enable-issues", "Disable issues with `--disable-issues`")
197		_ = cmd.Flags().MarkDeprecated("enable-wiki", "Disable wiki with `--disable-wiki`")
198	
199		_ = cmd.RegisterFlagCompletionFunc("gitignore", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
200			httpClient, err := opts.HttpClient()
201			if err != nil {
202				return nil, cobra.ShellCompDirectiveError
203			}
204			cfg, err := opts.Config()
205			if err != nil {
206				return nil, cobra.ShellCompDirectiveError
207			}
208			hostname, _ := cfg.DefaultHost()
209			results, err := listGitIgnoreTemplates(httpClient, hostname)
210			if err != nil {
211				return nil, cobra.ShellCompDirectiveError
212			}
213			return results, cobra.ShellCompDirectiveNoFileComp
214		})
215	
216		_ = cmd.RegisterFlagCompletionFunc("license", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
217			httpClient, err := opts.HttpClient()
218			if err != nil {
219				return nil, cobra.ShellCompDirectiveError
220			}
221			cfg, err := opts.Config()
222			if err != nil {
223				return nil, cobra.ShellCompDirectiveError
224			}
225			hostname, _ := cfg.DefaultHost()
226			licenses, err := listLicenseTemplates(httpClient, hostname)
227			if err != nil {
228				return nil, cobra.ShellCompDirectiveError
229			}
230			var results []string
231			for _, license := range licenses {
232				results = append(results, fmt.Sprintf("%s\t%s", license.Key, license.Name))
233			}
234			return results, cobra.ShellCompDirectiveNoFileComp
235		})
236	
237		return cmd
238	}
