240	func createRun(opts *CreateOptions) error {
241		fromScratch := opts.Source == ""
242	
243		if opts.Interactive {
244			selected, err := opts.Prompter.Select("What would you like to do?", "", []string{
245				"Create a new repository on GitHub from scratch",
246				"Push an existing local repository to GitHub",
247			})
248			if err != nil {
249				return err
250			}
251			fromScratch = selected == 0
252		}
253	
254		if fromScratch {
255			return createFromScratch(opts)
256		}
257		return createFromLocal(opts)
258	}
